from pathlib import Path
import base64, shutil, datetime

ROOT = Path("/content/mechguard_repo/website")
PAGE = ROOT / "src/app/page.tsx"
CSS = ROOT / "src/app/globals.css"
if not PAGE.exists() or not CSS.exists():
    raise SystemExit(f"❌ Expected files not found under {ROOT}")

# Safety backup
stamp=datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
shutil.copy2(PAGE, PAGE.with_name(f"page.tsx.before_restore_{stamp}"))
shutil.copy2(CSS, CSS.with_name(f"globals.css.before_restore_{stamp}"))

def dec(s): return base64.b64decode(s).decode().splitlines()

current=PAGE.read_text().splitlines()
if len(current) < 900:
    raise SystemExit(f"❌ page.tsx is unexpectedly short: {len(current)} lines")

# The saved compact version preserved the first 329 lines and the existing
# workspace middle was not included in the saved paste. Restore the recovered
# sections around that unchanged middle.
seg_a=dec('')
seg_b=dec('')
restored=current[:329] + seg_a + current[759:899] + seg_b
PAGE.write_text("\n".join(restored)+"\n")

# Restore the exact saved compact-layout overrides.
compact_css=dec('')
css_text=CSS.read_text()
marker="/* MECHGUARD FINAL COMPACT PRODUCT LAYOUT */"
if marker not in css_text:
    CSS.write_text(css_text.rstrip()+"\n\n"+"\n".join(compact_css)+"\n")

# Make the existing theme button pick up the restored compact styling without changing its behavior.
p=PAGE.read_text()
p=p.replace('className="group flex h-10 items-center gap-2 rounded-full', 'className="mechguard-theme-toggle group flex h-10 items-center gap-2 rounded-full', 1)
PAGE.write_text(p)

print("✅ RESTORED SAVED COMPACT MECHGUARD VERSION")
print("page.tsx:", len(PAGE.read_text().splitlines()), "lines")
print("Backup created with timestamp:", stamp)
